let allowed: Set<string> | null = null;

export function isAllowed(word: string): boolean {
  if (!allowed) {
    allowed = new Set();
    for (let i = 0; i < PACKED.length; i += 5) allowed.add(PACKED.slice(i, i + 5));
  }
  return allowed.has(word);
}
